import { INPUT_VALIDATION_FAILED } from "../../errors/index.js";
import { formatSchemaValidationErrors, toSchemaValidationErrors, } from "../../schemas/validation-errors.js";
/**
 * Parse submitted input against the declared inputSchema. Invalid input fails
 * before building or executing steps, with INPUT_VALIDATION_FAILED and the validation
 * errors in `context.errors` (veryfront/veryfront-issue-inbox#2091).
 */
export function parseWorkflowInput(workflow, input) {
    if (!workflow.inputSchema)
        return input;
    const result = workflow.inputSchema.safeParse(input);
    if (result.success)
        return result.data;
    const errors = toSchemaValidationErrors(result.issues ?? []);
    throw INPUT_VALIDATION_FAILED.create({
        detail: `Workflow "${workflow.id}" input failed inputSchema validation: ${formatSchemaValidationErrors(errors)}`,
        context: { errors },
    });
}
